package dev.interview.orders.fulfillment;
import com.fasterxml.jackson.databind.*; import dev.interview.orders.order.*; import dev.interview.orders.outbox.*; import org.springframework.cache.annotation.CacheEvict; import org.springframework.kafka.annotation.KafkaListener; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Component public class FulfillmentConsumer {private final ObjectMapper json;private final OrderRepository orders;private final ProcessedEventRepository processed;public FulfillmentConsumer(ObjectMapper j,OrderRepository o,ProcessedEventRepository p){json=j;orders=o;processed=p;}
 @KafkaListener(topics="orders.v1",groupId="fulfillment-v1") @Transactional @CacheEvict(cacheNames="orders",key="#result")
 public UUID consume(String payload)throws Exception{JsonNode e=json.readTree(payload);UUID eventId=UUID.fromString(e.required("eventId").asText());UUID orderId=UUID.fromString(e.required("orderId").asText());if(processed.existsById(eventId))return orderId;var order=orders.findById(orderId).orElseThrow();if(order.getStatus()==OrderStatus.CREATED)order.transitionTo(OrderStatus.ACCEPTED);processed.save(new ProcessedEvent(eventId));return orderId;}}
